// ── env.ts ──
import { z } from 'zod';

export const env = z
  .object({
    PORT: z.coerce.number().int().positive().default(3000),
    REDIS_URL: z.url().default('redis://127.0.0.1:6379'),
    WORKER_CONCURRENCY: z.coerce.number().int().positive().default(5),
  })
  .parse(process.env);

// ── jobs.ts ──
import { Queue, type JobsOptions } from 'bullmq';
import { Redis } from 'ioredis';
import { env } from './env.ts';

export const QUEUE = 'relatorios';

export interface JobDataMap { 'gerar-relatorio': { userId: string; mes: string } }
export interface JobResultMap { 'gerar-relatorio': { url: string; linhas: number } }
export type JobName = keyof JobDataMap;
export type RelatoriosQueue = Queue<JobDataMap[JobName], JobResultMap[JobName], JobName>;

export const createConnection = () => new Redis(env.REDIS_URL, { maxRetriesPerRequest: null });

export function createQueue(connection: Redis, nome = QUEUE): RelatoriosQueue {
  return new Queue<JobDataMap[JobName], JobResultMap[JobName], JobName>(nome, {
    connection,
    defaultJobOptions: {
      attempts: 3,
      backoff: { type: 'exponential', delay: 1_000 },
      removeOnComplete: { age: 24 * 60 * 60 }, // em segundos: o resultado fica 24h consultável
      removeOnFail: { age: 7 * 24 * 60 * 60 },
    },
  });
}

export function enqueue<K extends JobName>(queue: RelatoriosQueue, name: K, data: JobDataMap[K], opts?: JobsOptions) {
  return queue.add(name, data, opts);
}

import Fastify from 'fastify';
import { z } from 'zod';
import { enqueue, type RelatoriosQueue } from './jobs.ts';

const PedidoRelatorio = z.object({
  userId: z.string().regex(/^[a-z0-9_]+$/),
  mes: z.string().regex(/^\d{4}-\d{2}$/, 'use AAAA-MM'),
});

export function buildApp(queue: RelatoriosQueue) {
  const app = Fastify({ logger: process.env.NODE_ENV !== 'test' });

  app.post('/relatorios', async (request, reply) => {
    const parsed = PedidoRelatorio.safeParse(request.body);
    if (!parsed.success) return reply.code(400).send({ erro: z.flattenError(parsed.error).fieldErrors });

    const { userId, mes } = parsed.data;
    // jobId determinístico: pedir o mesmo relatório de novo devolve o job existente
    const job = await enqueue(queue, 'gerar-relatorio', { userId, mes }, { jobId: `relatorio-${userId}-${mes}` });

    // 202 Accepted: "recebi e vou processar". O cliente consulta o status depois.
    return reply.code(202).header('location', `/relatorios/${job.id}`).send({ id: job.id, status: 'na-fila' });
  });

  app.get<{ Params: { id: string } }>('/relatorios/:id', async (request, reply) => {
    const job = await queue.getJob(request.params.id);
    if (!job) return reply.code(404).send({ erro: 'relatório não encontrado' });

    const estado = await job.getState(); // 'waiting' | 'active' | 'delayed' | 'completed' | 'failed' | ...
    if (estado === 'completed') return { id: job.id, status: 'pronto', resultado: job.returnvalue };
    if (estado === 'failed') return { id: job.id, status: 'falhou', motivo: job.failedReason };
    return { id: job.id, status: estado, progresso: job.progress };
  });

  return app;
}

import { Worker, type Job } from 'bullmq';
import { setTimeout as sleep } from 'node:timers/promises';
import { env } from './env.ts';
import { QUEUE, createConnection, type JobDataMap, type JobName, type JobResultMap } from './jobs.ts';

type Handlers = {
  [K in JobName]: (job: Job<JobDataMap[K], JobResultMap[K], K>) => Promise<JobResultMap[K]>;
};

const handlers: Handlers = {
  'gerar-relatorio': async (job) => {
    for (const pct of [25, 50, 75, 100]) {
      await sleep(300); // consulta pesada ao banco, simulada
      await job.updateProgress(pct);
    }
    return { url: `/arquivos/${job.data.userId}-${job.data.mes}.pdf`, linhas: 1234 };
  },
};

function dispatch<K extends JobName>(job: Job<JobDataMap[K], JobResultMap[K], K>) {
  return handlers[job.name](job);
}

const connection = createConnection();
const worker = new Worker<JobDataMap[JobName], JobResultMap[JobName], JobName>(QUEUE, (job) => dispatch(job), {
  connection,
  concurrency: env.WORKER_CONCURRENCY,
});

worker.on('completed', (job) => console.log(`✔ ${job.name}#${job.id}`));
worker.on('failed', (job, err) => console.error(`✖ ${job?.name}#${job?.id}: ${err.message}`));
worker.on('error', (err) => console.error('erro no worker:', err.message));

for (const sinal of ['SIGINT', 'SIGTERM'] as const) {
  process.once(sinal, async () => {
    await worker.close(); // termina os jobs em andamento antes de sair
    await connection.quit();
    process.exit(0);
  });
}
console.log(`worker ouvindo "${QUEUE}" com concorrência ${env.WORKER_CONCURRENCY}`);

// ── server.ts ──
import { buildApp } from './api.ts';
import { env } from './env.ts';
import { createConnection, createQueue } from './jobs.ts';

const connection = createConnection();
const app = buildApp(createQueue(connection));
await app.listen({ port: env.PORT, host: '0.0.0.0' });

for (const sinal of ['SIGINT', 'SIGTERM'] as const) {
  process.once(sinal, async () => {
    await app.close(); // termina as requisições em andamento
    await connection.quit();
    process.exit(0);
  });
}

# docker-compose.yml
services:
  redis:
    image: redis:7.4-alpine
    command: ["redis-server", "--maxmemory-policy", "noeviction"]
  api:
    build: .
    command: ["node", "src/server.ts"]
    environment: { REDIS_URL: "redis://redis:6379", PORT: "3000" }
    ports: ["3000:3000"]
    depends_on: [redis]
  worker:
    build: .
    command: ["node", "src/worker.ts"]
    environment: { REDIS_URL: "redis://redis:6379", WORKER_CONCURRENCY: "5" }
    depends_on: [redis]

# Dockerfile (o mesmo para api e worker)
FROM node:24-alpine
WORKDIR /app
COPY package*.json ./
RUN npm ci --omit=dev
COPY src ./src

# Subir com 3 workers dividindo a fila:
#   docker compose up --build --scale worker=3
